166	        const budget = await response.json();
167	        document.getElementById('budget-initial').textContent = budget.initial_budget;
168	        document.getElementById('budget-used').textContent = budget.used_budget;
169	        document.getElementById('budget-remaining').textContent = budget.remaining_budget;
170	      } catch (error) {
171	        for (const key of ['initial', 'used', 'remaining']) {
172	          document.getElementById(`budget-${key}`).textContent = '不可用';
173	        }
174	      }
175	    }
176	
177	    function describeFilters(filters) {
178	      const entries = Object.entries(filters || {});
179	      if (!entries.length) return '（无筛选）';
180	      return entries.map(([field, value]) => `${field}=${value}`).join('，');
181	    }
182	
183	    async function refreshHistory() {
184	      const container = document.getElementById('releases');
185	      try {
186	        const response = await fetch('/api/releases');
187	        if (!response.ok) throw new Error(`HTTP ${response.status}`);
188	        const releases = await response.json();
189	        container.textContent = '';
190	        if (!releases.length) {
191	          const empty = document.createElement('p');
192	          empty.className = 'empty';
193	          empty.textContent = '暂无发布记录。';
194	          container.append(empty);
195	          return;
196	        }
197	        for (const release of releases) {
198	          const card = document.createElement('article');
199	          card.className = 'release-card';
200	          const title = document.createElement('h3');
201	          title.textContent = `发布计数 ${release.published_count}`;
202	          const details = document.createElement('dl');
203	          const items = [
204	            ['筛选条件', describeFilters(release.filters)],
205	            ['ε', release.epsilon],
206	            ['剩余预算', release.remaining_budget],
207	            ['发布时间', new Date(release.created_at).toLocaleString()],
208	            ['request_id', release.request_id],
209	            ['release_id', release.release_id],
210	          ];
211	          for (const [label, value] of items) {
212	            const dt = document.createElement('dt');
213	            dt.textContent = label;
214	            const dd = document.createElement('dd');
215	            dd.textContent = value;
216	            details.append(dt, dd);
217	          }
218	          card.append(title, details);
219	          container.append(card);
220	        }
221	      } catch (error) {
222	        container.textContent = `发布历史暂时不可用：${error.message}`;
223	      }
224	    }
225	
226	    function formatError(data, status) {
227	      if (data && typeof data.detail === 'string') return data.detail;
228	      if (data && Array.isArray(data.detail)) {
229	        return data.detail
230	          .map(item => `${(item.loc || []).filter(part => part !== 'body').join('.')}: ${item.msg}`)
231	          .join('；');
232	      }
233	      return `请求失败（HTTP ${status}）`;
234	    }
235	
236	    document.getElementById('release-form').addEventListener('submit', async (event) => {
237	      event.preventDefault();
238	      const message = document.getElementById('release-message');
239	      const button = document.getElementById('publish-button');
240	      const filters = {};
241	      for (const field of FILTER_FIELDS) {
242	        const value = document.getElementById(`filter-${field}`).value.trim();
243	        if (value) filters[field] = value;
244	      }
245	      const payload = {
246	        request_id: document.getElementById('request-id').value.trim(),
247	        dataset_id: 'retail-demo',
248	        filters: Object.keys(filters).length ? filters : null,
249	        epsilon: parseFloat(document.getElementById('epsilon').value),
250	      };
251	      message.className = '';
252	      message.textContent = '';
253	      button.disabled = true;
254	      try {
255	        const response = await fetch('/api/releases', {
256	          method: 'POST',
257	          headers: { 'Content-Type': 'application/json' },
258	          body: JSON.stringify(payload),
259	        });
260	        const data = await response.json().catch(() => null);
261	        if (!response.ok) {
262	          message.className = 'error';
263	          message.textContent = `发布失败：${formatError(data, response.status)}`;
264	          return;
265	        }
266	        message.className = 'success';
267	        message.textContent = `已发布计数 ${data.published_count}（剩余预算 ${data.remaining_budget}）。`;
268	        document.getElementById('request-id').value = newRequestId();
269	        await Promise.all([refreshBudget(), refreshHistory()]);
270	      } catch (error) {
271	        message.className = 'error';
272	        message.textContent = `发布失败：${error.message}`;
273	      } finally {
274	        button.disabled = false;
275	      }
276	    });
277	
278	    document.getElementById('request-id').value = newRequestId();
279	    loadCatalog();
280	    refreshBudget();
281	    refreshHistory();
282	
283	    function localInputToIso(value) {
284	      if (!value) return '';
285	      return new Date(value).toISOString();
286	    }
287	
288	    document.getElementById('export-form').addEventListener('submit', async (event) => {
289	      event.preventDefault();
290	      const message = document.getElementById('export-message');
291	      const button = document.getElementById('export-button');
292	      const params = new URLSearchParams();
293	      params.set('format', document.getElementById('export-format').value);
294	      const datasetId = document.getElementById('export-dataset').value;
295	      if (datasetId) params.set('dataset_id', datasetId);
