  const createdShares = [];

  function shareStatus(share) {
    if (share.revoked) return { label: '已撤销', className: 'status-revoked' };
    if (new Date(share.expires_at).getTime() <= Date.now()) {
      return { label: '已过期', className: 'status-expired' };
    }
    return { label: '有效', className: 'status-active' };
  }

  function shareUrl(token) {
    return `${location.origin}/api/shares/${token}/releases`;
  }

  function describeShareScope(share) {
    const parts = [];
    parts.push(share.request_id ? `request_id=${share.request_id}` : '全部请求');
    parts.push(share.from ? `from ${new Date(share.from).toLocaleString()}` : '不限起点');
    parts.push(share.to ? `to ${new Date(share.to).toLocaleString()}` : '不限终点');
    parts.push(`limit ${share.limit}`);
    return parts.join(' · ');
  }

  async function copyShareLink(token, button) {
    const url = shareUrl(token);
    try {
      await navigator.clipboard.writeText(url);
      button.textContent = '已复制';
    } catch (_) {
      const input = document.querySelector(`input[data-share-token="${token}"]`);
      if (input) {
        input.focus();
        input.select();
        document.execCommand('copy');
        button.textContent = '已复制';
      }
    }
    setTimeout(() => { button.textContent = '复制链接'; }, 2000);
  }

  async function revokeShare(token) {
    const share = createdShares.find(item => item.token === token);
    const message = document.getElementById('share-message');
    try {
      const response = await fetch(`/api/shares/${token}`, { method: 'DELETE' });
      if (!response.ok && response.status !== 204) {
        const data = await response.json().catch(() => null);
        message.className = 'error';
        message.textContent = `撤销失败：${formatError(data, response.status)}`;
        return;
      }
      if (share) share.revoked = true;
      message.className = 'success';
      message.textContent = '分享已撤销，链接立即失效。';
      renderShares();
    } catch (error) {
      message.className = 'error';
      message.textContent = `撤销失败：${error.message}`;
    }
  }

  function renderShares() {
    const container = document.getElementById('shares');
    container.textContent = '';
    if (!createdShares.length) return;
    for (const share of createdShares) {
      const status = shareStatus(share);
      const card = document.createElement('article');
      card.className = 'release-card';
      const title = document.createElement('h3');
      const badge = document.createElement('span');
      badge.className = `status-badge ${status.className}`;
      badge.textContent = status.label;
      title.append('分享链接 ', badge);
      const details = document.createElement('dl');
      const items = [
        ['范围', describeShareScope(share)],
        ['过期时间', new Date(share.expires_at).toLocaleString()],
        ['创建时间', new Date(share.created_at).toLocaleString()],
        ['share_id', share.share_id],
      ];
      for (const [label, value] of items) {
        const dt = document.createElement('dt');
        dt.textContent = label;
        const dd = document.createElement('dd');
        dd.textContent = value;
        details.append(dt, dd);
      }
      const actions = document.createElement('div');
      actions.className = 'share-actions';
      const linkInput = document.createElement('input');
      linkInput.readOnly = true;
      linkInput.value = shareUrl(share.token);
      linkInput.setAttribute('data-share-token', share.token);
      linkInput.addEventListener('focus', () => linkInput.select());
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'secondary';
      copyButton.textContent = '复制链接';
      copyButton.addEventListener('click', () => copyShareLink(share.token, copyButton));
      const revokeButton = document.createElement('button');
      revokeButton.type = 'button';
      revokeButton.className = 'danger';
      revokeButton.textContent = '撤销';
      revokeButton.disabled = share.revoked || status.label === '已过期';
      revokeButton.addEventListener('click', () => revokeShare(share.token));
      actions.append(linkInput, copyButton, revokeButton);
      card.append(title, details, actions);
      container.append(card);
    }
  }

  document.getElementById('share-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const message = document.getElementById('share-message');
    const button = document.getElementById('share-button');
    const payload = { dataset_id: 'retail-demo' };
    const requestId = document.getElementById('share-request-id').value.trim();
    if (requestId) payload.request_id = requestId;
    const fromIso = localInputToIso(document.getElementById('share-from').value);
    const toIso = localInputToIso(document.getElementById('share-to').value);
    if (fromIso) payload.from = fromIso;
    if (toIso) payload.to = toIso;
    const limitRaw = document.getElementById('share-limit').value;
    const limit = Number.parseInt(limitRaw, 10);
    if (limitRaw === '' || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      message.className = 'error';
      message.textContent = '创建分享失败：limit 必须是 1–100 的整数。';
      return;
    }
    payload.limit = limit;
    const expiresIso = localInputToIso(document.getElementById('share-expires').value);
    if (!expiresIso) {
      message.className = 'error';
      message.textContent = '创建分享失败：必须填写过期时间。';
      return;
    }
    payload.expires_at = expiresIso;
    if (fromIso && toIso && new Date(fromIso) >= new Date(toIso)) {
      message.className = 'error';
      message.textContent = '创建分享失败：起始时间必须早于结束时间。';
      return;
    }
    message.className = '';
    message.textContent = '';
    button.disabled = true;
    try {
      const response = await fetch('/api/shares', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        message.className = 'error';
        message.textContent = `创建分享失败：${formatError(data, response.status)}`;
        return;
      }
      createdShares.unshift({ ...data, revoked: false });
      renderShares();
      message.className = 'success';
      message.textContent = '分享已创建，复制链接发送给合作方；链接到期或撤销后自动失效。';
    } catch (error) {
      message.className = 'error';
      message.textContent = `创建分享失败：${error.message}`;
    } finally {
      button.disabled = false;
    }
  });

  setInterval(renderShares, 30000);
</script>

