      const actions = document.createElement('div');
      actions.className = 'share-actions';
      const linkInput = document.createElement('input');
      linkInput.readOnly = true;
      linkInput.value = shareUrl(share.token);
      linkInput.setAttribute('data-share-token', share.token);
      linkInput.addEventListener('focus', () => linkInput.select());
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'secondary';
      copyButton.textContent = '复制链接';
      copyButton.addEventListener('click', () => copyShareLink(share.token, copyButton));
      const revokeButton = document.createElement('button');
      revokeButton.type = 'button';
      revokeButton.className = 'danger';
      revokeButton.textContent = '撤销';
      revokeButton.disabled = share.revoked || status.label === '已过期';
      revokeButton.addEventListener('click', () => revokeShare(share.token));
      actions.append(linkInput, copyButton, revokeButton);
      card.append(title, details, actions);
      container.append(card);
    }
  }

  document.getElementById('share-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const message = document.getElementById('share-message');
    const button = document.getElementById('share-button');
    const payload = { dataset_id: 'retail-demo' };
    const requestId = document.getElementById('share-request-id').value.trim();
    if (requestId) payload.request_id = requestId;
    const fromIso = localInputToIso(document.getElementById('share-from').value);
    const toIso = localInputToIso(document.getElementById('share-to').value);
    if (fromIso) payload.from = fromIso;
    if (toIso) payload.to = toIso;
    const limitRaw = document.getElementById('share-limit').value;
    const limit = Number.parseInt(limitRaw, 10);
    if (limitRaw === '' || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      message.className = 'error';
      message.textContent = '创建分享失败：limit 必须是 1–100 的整数。';
      return;
    }
    payload.limit = limit;
    const expiresIso = localInputToIso(document.getElementById('share-expires').value);
    if (!expiresIso) {
      message.className = 'error';
      message.textContent = '创建分享失败：必须填写过期时间。';
      return;
    }
    payload.expires_at = expiresIso;
    if (fromIso && toIso && new Date(fromIso) >= new Date(toIso)) {
      message.className = 'error';
      message.textContent = '创建分享失败：起始时间必须早于结束时间。';
      return;
    }
    message.className = '';
    message.textContent = '';
    button.disabled = true;
    try {
      const response = await fetch('/api/shares', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        message.className = 'error';
        message.textContent = `创建分享失败：${formatError(data, response.status)}`;
        return;
      }
      createdShares.unshift({ ...data, revoked: false });
      renderShares();
      message.className = 'success';
      message.textContent = '分享已创建，复制链接发送给合作方；链接到期或撤销后自动失效。';
    } catch (error) {
      message.className = 'error';
      message.textContent = `创建分享失败：${error.message}`;
    } finally {
      button.disabled = false;
    }
  });

  setInterval(renderShares, 30000);
</script>
